	'@seo_xe_d1' => array( 'en' => 'Custom-fit ambient lighting for the {xe}: OEM-style LED trims, no wire cutting, app and button control. Kits from {gia}. Chat on WhatsApp.', 'zh' => '{xe} 专车定制氛围灯：原厂式 LED 饰板，无需剪线，App 与按键控制。套装 {gia} 起，欢迎 WhatsApp 咨询。', 'ko' => '{xe} 전용 앰비언트 라이트: 순정형 LED 트림, 배선 절단 없음, 앱·버튼 제어. 키트 {gia}부터, WhatsApp 문의 환영.', 'th' => 'ไฟแอมเบียนท์เข้ารูปสำหรับ {xe}: ครอบ LED แบบของเดิม ไม่ต้องตัดสายไฟ ควบคุมด้วยแอปและปุ่ม ชุดไฟเริ่มต้น {gia} ทัก WhatsApp ได้เลย', 'de' => 'Passgenaue Ambientebeleuchtung für den {xe}: LED-Blenden im Originalstil, ohne Kabel zu trennen, per App steuerbar. Ab {gia}. Jetzt per WhatsApp anfragen.', 'hi' => '{xe} के लिए कस्टम-फ़िट एम्बिएंट लाइटिंग: OEM-स्टाइल LED ट्रिम, बिना तार काटे, ऐप और बटन से नियंत्रण। {gia} से शुरू। WhatsApp करें।' ),
	'@seo_xe_d2' => array( 'en' => 'Custom-fit ambient lighting for the {xe}: OEM-style LED trims, no wire cutting, app control. From {gia}.', 'zh' => '{xe} 专车定制氛围灯：原厂式 LED 饰板，无需剪线，App 控制，{gia} 起。', 'ko' => '{xe} 전용 앰비언트 라이트: 순정형 LED 트림, 배선 절단 없음, 앱 제어. {gia}부터.', 'th' => 'ไฟแอมเบียนท์เข้ารูปสำหรับ {xe}: ครอบ LED แบบของเดิม ไม่ตัดสายไฟ ควบคุมผ่านแอป เริ่มต้น {gia}', 'de' => 'Ambientebeleuchtung für den {xe}: LED-Blenden im Originalstil, ohne Kabel zu trennen, per App. Ab {gia}.', 'hi' => '{xe} के लिए कस्टम-फ़िट एम्बिएंट लाइटिंग: OEM-स्टाइल LED ट्रिम, बिना तार काटे, ऐप कंट्रोल। {gia} से।' ),
	'@seo_hang_d' => array( 'en' => 'Custom-fit interior ambient lighting kits for %s: OEM-style LED trims for each model and year, app control. Chat with SK on WhatsApp.', 'zh' => '%s 专车定制车内氛围灯套件：按车型年款设计的原厂式 LED 饰板，App 控制。欢迎通过 WhatsApp 咨询 SK。', 'ko' => '%s 전용 실내 앰비언트 라이트 키트: 차종·연식별 순정형 LED 트림, 앱 제어. WhatsApp으로 SK에 문의하세요.', 'th' => 'ชุดไฟแอมเบียนท์ภายในเข้ารูปสำหรับ %s: ครอบ LED แบบของเดิมตามรุ่นและปี ควบคุมผ่านแอป ทัก SK ทาง WhatsApp', 'de' => 'Passgenaue Ambientebeleuchtung für %s: LED-Blenden im Originalstil für jedes Modell und Baujahr, per App steuerbar. Fragen Sie SK per WhatsApp.', 'hi' => '%s के लिए कस्टम-फ़िट इंटीरियर एम्बिएंट लाइटिंग किट: हर मॉडल और साल के लिए OEM-स्टाइल LED ट्रिम, ऐप कंट्रोल। SK से WhatsApp पर बात करें।' ),
	'@seo_ds_d' => array( 'en' => 'Interior ambient lighting kits made for each car model: Toyota, Honda, Mazda, Hyundai, Kia, Ford, VinFast and more. See kits and prices.', 'zh' => '按车型定制的车内氛围灯套件：丰田、本田、马自达、现代、起亚、福特、VinFast 等。查看套装与价格。', 'ko' => '차종별 맞춤 실내 앰비언트 라이트 키트: 토요타, 혼다, 마쓰다, 현대, 기아, 포드, VinFast 등. 키트와 가격을 확인하세요.', 'th' => 'ชุดไฟแอมเบียนท์ภายในตามรุ่นรถ: Toyota, Honda, Mazda, Hyundai, Kia, Ford, VinFast และอื่น ๆ ดูชุดไฟและราคา', 'de' => 'Ambientebeleuchtung für jedes Fahrzeugmodell: Toyota, Honda, Mazda, Hyundai, Kia, Ford, VinFast und mehr. Sets und Preise ansehen.', 'hi' => 'हर कार मॉडल के लिए इंटीरियर एम्बिएंट लाइटिंग किट: Toyota, Honda, Mazda, Hyundai, Kia, Ford, VinFast और अन्य। किट और कीमतें देखें।' ),
	'@seo_home_d' => array( 'en' => 'SK Ambient Light: premium car interior ambient lighting – OEM-style replacement trims for each model, no wire cutting, app control. Chat on WhatsApp.', 'zh' => 'SK Ambient Light 高端汽车车内氛围灯：按车型定制的原厂式替换饰板，无需剪线，App 控制。欢迎 WhatsApp 咨询。', 'ko' => 'SK Ambient Light 프리미엄 차량 실내 앰비언트 라이트: 차종별 순정형 교체 트림, 배선 절단 없음, 앱 제어. WhatsApp 문의.', 'th' => 'SK Ambient Light ไฟแอมเบียนท์ภายในรถระดับพรีเมียม: ครอบแทนของเดิมตามรุ่นรถ ไม่ต้องตัดสายไฟ ควบคุมผ่านแอป ทัก WhatsApp', 'de' => 'SK Ambient Light: Premium-Ambientebeleuchtung – Austauschblenden im Originalstil für jedes Modell, ohne Kabel zu trennen, per App. Per WhatsApp anfragen.', 'hi' => 'SK Ambient Light: प्रीमियम कार इंटीरियर एम्बिएंट लाइटिंग – हर मॉडल के लिए OEM-स्टाइल ट्रिम, बिना तार काटे, ऐप कंट्रोल। WhatsApp करें।' ),
	'@seo_gt_d' => array( 'en' => 'SK Ambient Light is a Vietnamese brand of custom-fit car ambient lighting: OEM-style LED trims for each model, app control, 24-month warranty.', 'zh' => 'SK Ambient Light 是越南汽车氛围灯品牌：按车型定制的原厂式 LED 饰板，App 控制，保修 24 个月。', 'ko' => 'SK Ambient Light는 베트남의 차량 앰비언트 라이트 브랜드입니다: 차종별 순정형 LED 트림, 앱 제어, 24개월 보증.', 'th' => 'SK Ambient Light แบรนด์ไฟแอมเบียนท์รถยนต์จากเวียดนาม: ครอบ LED แบบของเดิมตามรุ่น ควบคุมผ่านแอป รับประกัน 24 เดือน', 'de' => 'SK Ambient Light ist eine vietnamesische Marke für passgenaue Ambientebeleuchtung: LED-Blenden im Originalstil, App-Steuerung, 24 Monate Garantie.', 'hi' => 'SK Ambient Light वियतनाम का कार एम्बिएंट लाइटिंग ब्रांड है: हर मॉडल के लिए OEM-स्टाइल LED ट्रिम, ऐप कंट्रोल, 24 महीने की वारंटी।' ),
	'@seo_lh_d' => array( 'en' => 'Contact SK Ambient Light on WhatsApp +84 868 055 555 for car ambient lighting kits, prices and international shipping. Based in Hanoi, Vietnam.', 'zh' => '通过 WhatsApp +84 868 055 555 联系 SK Ambient Light，咨询汽车氛围灯套件、价格及国际运输。公司位于越南河内。', 'ko' => 'WhatsApp +84 868 055 555로 SK Ambient Light에 차량 앰비언트 라이트 키트, 가격, 해외 배송을 문의하세요. 베트남 하노이 소재.', 'th' => 'ติดต่อ SK Ambient Light ทาง WhatsApp +84 868 055 555 สอบถามชุดไฟแอมเบียนท์รถยนต์ ราคา และการจัดส่งต่างประเทศ ตั้งอยู่ที่ฮานอย เวียดนาม', 'de' => 'SK Ambient Light per WhatsApp +84 868 055 555 kontaktieren: Ambientebeleuchtung, Preise und internationaler Versand. Sitz in Hanoi, Vietnam.', 'hi' => 'कार एम्बिएंट लाइटिंग किट, कीमत और अंतरराष्ट्रीय शिपिंग के लिए SK Ambient Light से WhatsApp +84 868 055 555 पर संपर्क करें। हनोई, वियतनाम में स्थित।' ),
